import re

def eval_expression(expr):
    # 1. トークナイズ: 数字、演算子、括弧を分離する
    # \d+\.?\d* : 整数または小数を抽出
    # [+\-*/()] : 演算子と括弧を抽出
    tokens = re.findall(r'\d+\.?\d*|[+\-*/()]', expr)
    pos = 0

    def peek():
        """現在のトークンを返す（ポインタは進めない）"""
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        """現在のトークンを返し、ポインタを1つ進める"""
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        """加算と減算を処理 (優先順位: 低)"""
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        """乗算と除算を処理 (優先順位: 中)"""
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        """数値、括弧、単項マイナスを処理 (優先順位: 高)"""
        token = peek()

        # 単項マイナスの処理 (例: -5)
        if token == '-':
            consume()
            return -parse_factor()

        # 括弧の処理
        if token == '(':
            consume() # '(' を消費
            result = parse_expression()
            consume() # ')' を消費
            return result

        # 数値の処理
        token = consume()
        if token is None:
            raise ValueError("Unexpected end of expression")
        return float(token)

    # 計算開始
    try:
        result = parse_expression()
        # 結果が整数（.0で終わる）なら整数型で返す
        return int(result) if result.is_integer() else result
    except IndexError:
        raise ValueError("Invalid expression")

# --- テストケース ---
if __name__ == "__main__":
    test_cases = [
        ("3 + 4 * (2 - 1)", 7),
        ("10 + 2 * 3", 16),
        ("(10 + 2) * 3", 36),
        ("-5 + 2", -3),
        ("10 / 2 / 5", 1),
        ("2 * (-3 + 1)", -4),
        ("--5", 5), # 二重マイナス
        ("10 / 0", "ZeroDivisionError"),
    ]

    for expression, expected in test_cases:
        try:
            res = eval_expression(expression)
            print(f"'{expression}' -> {res} (Expected: {expected})")
        except ZeroDivisionError:
            print(f"'{expression}' -> ZeroDivisionError (Expected: {expected})")
        except Exception as e:
            print(f"'{expression}' -> Error: {e}")
